//! Reclaim a byte-identical index generated by a closed epoch 230 hourly replay.
use super::{
    appendvec288::lock_issuer, appendvec292::failed::no_readers, selective_accounts::record,
    snapshot288::lookup_receipt, *,
};
use std::ffi::CString;

const NAME: &str = "epoch-230-bafyreiagquwjabddakpmoxczj7mrtn4rpddn3ybzz7zltpg2xpkrta5r7q-mainnet-cid-to-offset-and-size.index";
const SOURCE: &str = "/home/ubuntu/.jetstreamer-private/epoch230-source-transport.2CDXkBBv/compact";
const BODY: &str = "c5ed39b5d14430a1b2ad70060bfb0d03ae1810d8905cf7348a1515b7c59026af";
const RECIPE: &str = "43b07efdb2768acd7602b42d376bfa356cd1bf157bd0563c5e32f07c5f8fc466";
const COMMAND: &str = "2958a5fdab5e30753652da911a1a4eb925eb2da9539ebda8bcfd037cfc3cd90e";
const ALLOCATED: u64 = 20_201_080 * 512;

pub(super) struct Replay {
    root: &'static str,
    state: &'static str,
    schema: &'static str,
    terminal_sha: &'static str,
    unit: &'static str,
    invocation: &'static str,
    parent_inode: u64,
    index_inode: u64,
    modified_ns: i128,
    changed_ns: i128,
}

pub(super) const FIRST: Replay = Replay {
    root: "/home/ubuntu/.jetstreamer-private/qualification-230-middle-hourly-first-v1",
    state: "/var/lib/jetstreamer/horizon230-middle-hourly-first-runtime-v1",
    schema: "foundation-epoch230-middle-hourly-first-terminal-v1",
    terminal_sha: "32bde0ced76922d9171b582a9a42322449b7b0f53b12b6dd2730ec19dd5215df",
    unit: "horizon-qualify-230-middle-hourly-first-v1.service",
    invocation: "763d461014f042f7bc4591a3b8ec9ac5",
    parent_inode: 102_148_451,
    index_inode: 102_148_951,
    modified_ns: 1_795_758_514_951_718_985,
    changed_ns: 1_795_758_514_982_719_084,
};

pub(super) const SECOND: Replay = Replay {
    root: "/home/ubuntu/.jetstreamer-private/qualification-230-middle-hourly-second-v1",
    state: "/var/lib/jetstreamer/horizon230-middle-hourly-second-runtime-v1",
    schema: "foundation-epoch230-middle-hourly-second-terminal-v1",
    terminal_sha: "2ed2322cffebec1575bc9ba4dea1894e9e710c3b970c9db504153869f70a9b56",
    unit: "horizon-qualify-230-middle-hourly-second-v1.service",
    invocation: "a0a94d2d42984804877c1a80fc934585",
    parent_inode: 19_318_107,
    index_inode: 19_318_110,
    modified_ns: 1_795_778_141_407_109_764,
    changed_ns: 1_795_778_141_623_110_443,
};

fn exact(replay: &Replay, m: &Metadata, original: bool) -> bool {
    let ns = |s: i64, f: i64| i128::from(s) * 1_000_000_000 + i128::from(f);
    let (inode, mode, blocks, modified, changed) = if original {
        (
            20_606_687,
            0o400,
            20_201_088,
            1_795_509_657_967_677_528,
            1_795_509_732_895_938_493,
        )
    } else {
        (
            replay.index_inode,
            0o600,
            20_201_080,
            replay.modified_ns,
            replay.changed_ns,
        )
    };
    m.is_file()
        && m.dev() == 66_305
        && m.ino() == inode
        && m.nlink() == 1
        && m.uid() == 1000
        && m.gid() == 1000
        && m.mode() & 0o7777 == mode
        && m.len() == 10_342_940_334
        && m.blocks() == blocks
        && ns(m.mtime(), m.mtime_nsec()) == modified
        && ns(m.ctime(), m.ctime_nsec()) == changed
}

fn readers(replay: &Replay, target: &Path) -> Result<Value> {
    assert_no_nested_mount(target)?;
    if replay.unit == SECOND.unit {
        terminal_unit(replay.unit)?;
        terminal_unit("horizon-230-middle-hourly-second-protective-v1.timer")?;
        return no_readers(
            Path::new(replay.root),
            target,
            &[(
                "horizon-230-middle-hourly-second-protective-v1.service",
                "ef7dadb3d12f492897967cb26bf07a65",
                "d038f1abe70e54d63846f379e4fbd51695160a11ec26215e843e7ba9789edc1c",
            )],
        );
    }
    let path = Path::new("/run/systemd/transient").join(replay.unit);
    ensure!(
        digest(&mut open_regular(&path)?)? == RECIPE,
        "changed epoch 230 terminal recipe"
    );
    let control = Command::new("/usr/bin/systemctl")
        .args([
            "show",
            replay.unit,
            "-p",
            "DropInPaths,FragmentPath,UnitFileState,Result",
        ])
        .output()?;
    let attrs = String::from_utf8(control.stdout)?;
    ensure!(
        control.status.success()
            && [
                "DropInPaths=".into(),
                format!("FragmentPath={}", path.display()),
                "UnitFileState=transient".into(),
                "Result=exit-code".into()
            ]
            .iter()
            .all(|p| attrs.lines().any(|line| line == p)),
        "unexpected epoch 230 terminal recipe state"
    );
    for unit in [
        "horizon-230-middle-hourly-first-protective-v1.service",
        "horizon-230-middle-hourly-first-protective-v1.timer",
    ] {
        terminal_unit(unit)?;
    }
    no_readers(
        Path::new(replay.root),
        target,
        &[(replay.unit, replay.invocation, COMMAND)],
    )
}

pub(super) fn run(replay: &Replay, apply: bool) -> Result<()> {
    let _issuer = lock_issuer()?;
    let _cycle = lock(CYCLE_LOCK)?;
    let _mutation = lock(LOCAL_LOCK)?;
    let state = Path::new(replay.state);
    let terminal_path = state.join("terminal.json");
    let terminal: Value = read_bound(&terminal_path, replay.terminal_sha, JSON_LIMIT)?;
    let complete = replay.unit == SECOND.unit;
    ensure!(
        terminal["schema"] == replay.schema
            && terminal["unit"] == replay.unit
            && terminal["invocation_id"] == replay.invocation
            && terminal["guard_drained"] == true
            && terminal["producer"]["Result"] == if complete { "success" } else { "exit-code" },
        "foreign epoch 230 terminal evidence"
    );
    let parent = Path::new(replay.root).join("work/output/compact-indexes/230");
    let source = Path::new(SOURCE).join(NAME);
    let target = parent.join(NAME);
    let (retained, length, field) = if complete {
        ensure!(
            terminal["state"] == "local-segment-committed" && terminal["slot_count"] == 39_522,
            "epoch 230 second segment did not close"
        );
        (
            &terminal["archive"],
            &terminal["archive_bytes"],
            "retained_archive",
        )
    } else {
        (
            &terminal["partial"],
            &terminal["partial"]["size"],
            "retained_partial",
        )
    };
    let archive = PathBuf::from(
        retained["path"]
            .as_str()
            .context("missing epoch 230 archive")?,
    );
    let archive_meta = open_regular(&archive)?.metadata()?;
    ensure!(
        archive.starts_with(replay.root)
            && archive != target
            && archive_meta.len() == *length
            && (!complete
                || (archive_meta.ino() == retained["identity"]["inode"]
                    && archive_meta.dev() == retained["identity"]["device"])),
        "retained epoch 230 archive changed"
    );
    let anchor = json!({"target":target,"keeper":source,"sha256":BODY,(field):archive,
        "terminal":{"path":terminal_path,"sha256":replay.terminal_sha},"target_inode":replay.index_inode,"keeper_inode":20_606_687});
    let intent_path = state.join("duplicate-index-retirement-intent.json");
    let done_path = state.join("duplicate-index-retirement-completion.json");
    let pending = lookup_receipt(&intent_path)?;
    let present = match target.symlink_metadata() {
        Ok(_) => true,
        Err(e) if e.kind() == io::ErrorKind::NotFound => false,
        Err(e) => return Err(e.into()),
    };
    if let Some((_, data)) = &pending {
        ensure!(
            data["evidence"] == anchor,
            "different epoch 230 retirement intent"
        );
    }
    if let Some((binding, data)) = lookup_receipt(&done_path)? {
        ensure!(
            pending.is_some()
                && !present
                && data["evidence"] == anchor
                && exact(replay, &open_regular(&source)?.metadata()?, true),
            "epoch 230 retirement completion conflicts with disk"
        );
        println!("{}", serde_json::to_string(&binding)?);
        return Ok(());
    }
    let dir = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_DIRECTORY | libc::O_NOFOLLOW)
        .open(&parent)?;
    let d = dir.metadata()?;
    ensure!(
        parent.canonicalize()? == parent
            && d.ino() == replay.parent_inode
            && d.dev() == 66_305
            && d.uid() == 1000
            && d.gid() == 1000
            && d.mode() & 0o7777 == 0o700,
        "epoch 230 generated-index parent changed"
    );
    let before = available(&parent)?;
    let mut keeper = open_regular(&source)?;
    ensure!(
        exact(replay, &keeper.metadata()?, true),
        "epoch 230 original index changed"
    );
    let intent = if present {
        let first = readers(replay, &target)?;
        let mut old = open_regular(&target)?;
        ensure!(
            exact(replay, &old.metadata()?, false)
                && digest(&mut old)? == BODY
                && digest(&mut keeper)? == BODY,
            "epoch 230 index bodies differ"
        );
        let second = readers(replay, &target)?;
        if !apply {
            ensure!(pending.is_none(), "epoch 230 retirement already started");
            println!(
                "{}",
                json!({"evidence":anchor,"allocated_bytes":ALLOCATED,"readers":second,
                "check_only":true,"retirement_performed":false})
            );
            return Ok(());
        }
        let intent = match pending {
            Some((binding, _)) => binding,
            None => record(
                &intent_path,
                &json!({"evidence":anchor,"allocated_bytes":ALLOCATED,
                "free_before_bytes":before,"readers_before_hashing":first,"readers_after_hashing":second}),
            )?,
        };
        ensure!(
            identity(&dir.metadata()?) == identity(&parent.symlink_metadata()?)
                && exact(replay, &old.metadata()?, false)
                && exact(replay, &target.symlink_metadata()?, false)
                && exact(replay, &keeper.metadata()?, true)
                && exact(replay, &source.symlink_metadata()?, true),
            "epoch 230 retirement endpoint changed before unlink"
        );
        let filename = CString::new(NAME)?;
        if unsafe { libc::unlinkat(dir.as_raw_fd(), filename.as_ptr(), 0) } != 0 {
            return Err(io::Error::last_os_error()).context("unlink exact stopped epoch 230 index");
        }
        dir.sync_all()?;
        ensure!(
            old.metadata()?.nlink() == 0,
            "retired epoch 230 index has another link"
        );
        intent
    } else {
        ensure!(apply, "epoch 230 duplicate already absent");
        dir.sync_all()?;
        pending
            .context("epoch 230 duplicate absent without a retirement intent")?
            .0
    };
    let done = record(
        &done_path,
        &json!({
            "schema":"foundation-epoch230-local-duplicate-index-retirement-v1","epoch":230,
            "evidence":anchor,"intent":intent,"allocated_bytes_removed":ALLOCATED,
            "free_at_attempt_start_bytes":before,"free_after_bytes":available(&parent)?,
            "remote_mutations":false
        }),
    )?;
    println!("{}", serde_json::to_string(&done)?);
    Ok(())
}
